import React, { useState, useEffect } from 'react';
import axios from 'axios';

const API_BASE = '/api/admin';

interface Driver {
  id: string;
  name: string | null;
  phone: string;
  vehicleType: string;
  kycStatus: string;
  createdAt: string;
}

interface KycResponse {
  drivers: Driver[];
  total: number;
  page: number;
  limit: number;
}

interface PaymentRecord {
  id: string;
  tripId: string;
  riderId: string;
  amount: number;
  status: string;
  createdAt: string;
}

interface TripReport {
  id: string;
  status: string;
  riderId: string;
  createdAt: string;
  estimatedFare: number | null;
  finalFare: number | null;
}

export default function Dashboard() {
  const [activeTab, setActiveTab] = useState<'kyc' | 'payments' | 'trips'>('kyc');
  const [kycData, setKycData] = useState<KycResponse | null>(null);
  const [payments, setPayments] = useState<PaymentRecord[]>([]);
  const [trips, setTrips] = useState<TripReport[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const token = localStorage.getItem('adminToken') || '';

  const fetchKycData = async () => {
    setLoading(true);
    try {
      const response = await axios.get<KycResponse>(`${API_BASE}/kyc/pending`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setKycData(response.data);
    } catch (err: any) {
      setError(err.message);
    }
    setLoading(false);
  };

  const fetchPayments = async () => {
    setLoading(true);
    try {
      const response = await axios.get<{ payments: PaymentRecord[] }>(`${API_BASE}/payments/search`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setPayments(response.data.payments);
    } catch (err: any) {
      setError(err.message);
    }
    setLoading(false);
  };

  const fetchTrips = async () => {
    setLoading(true);
    try {
      const response = await axios.get<{ trips: TripReport[] }>(`${API_BASE}/trips/reports`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setTrips(response.data.trips);
    } catch (err: any) {
      setError(err.message);
    }
    setLoading(false);
  };

  const handleApprove = async (driverId: string) => {
    await axios.post(`${API_BASE}/kyc/${driverId}/approve`, {}, {
      headers: { Authorization: `Bearer ${token}` }
    });
    fetchKycData();
  };

  const handleReject = async (driverId: string, reason: string) => {
    await axios.post(`${API_BASE}/kyc/${driverId}/reject`, { reason }, {
      headers: { Authorization: `Bearer ${token}` }
    });
    fetchKycData();
  };

  useEffect(() => {
    fetchKycData();
  }, []);

  return (
    <div className="dashboard">
      <div className="dashboard-header">
        <h1>Admin Dashboard</h1>
        <div className="dashboard-tabs">
          <button className={`tab ${activeTab === 'kyc' ? 'active' : ''}`} onClick={() => { setActiveTab('kyc'); fetchKycData(); }}>
            KYC Management ({kycData?.total || 0})
          </button>
          <button className={`tab ${activeTab === 'payments' ? 'active' : ''}`} onClick={() => { setActiveTab('payments'); fetchPayments(); }}>
            Payments
          </button>
          <button className={`tab ${activeTab === 'trips' ? 'active' : ''}`} onClick={() => { setActiveTab('trips'); fetchTrips(); }}>
            Trip Reports
          </button>
        </div>
      </div>

      {loading && <div className="loading">Loading...</div>}
      {error && <div className="error">Error: {error}</div>}

      {activeTab === 'kyc' && (
        <div className="tab-content">
          <h2>Pending KYC Approvals</h2>
          {kycData?.drivers && kycData.drivers.length > 0 ? (
            <table className="data-table">
              <thead>
                <tr><th>Driver</th><th>Phone</th><th>Vehicle</th><th>Status</th><th>Actions</th></tr>
              </thead>
              <tbody>
                {kycData.drivers.map(driver => (
                  <tr key={driver.id}>
                    <td>{driver.name || 'Unknown'}</td>
                    <td>{driver.phone}</td>
                    <td>{driver.vehicleType}</td>
                    <td>{driver.kycStatus}</td>
                    <td>
                      <button onClick={() => handleApprove(driver.id)} className="btn-approve">Approve</button>
                      <button onClick={() => { const reason = prompt('Enter rejection reason:'); if (reason) handleReject(driver.id, reason); }} className="btn-reject">Reject</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <p>No pending KYC applications</p>
          )}
        </div>
      )}

      {activeTab === 'payments' && (
        <div className="tab-content">
          <h2>Payment History</h2>
          <table className="data-table">
            <thead>
              <tr><th>Payment ID</th><th>Trip ID</th><th>Rider</th><th>Amount</th><th>Status</th><th>Date</th></tr>
            </thead>
            <tbody>
              {payments.map(payment => (
                <tr key={payment.id}>
                  <td>{payment.id}</td>
                  <td>{payment.tripId}</td>
                  <td>{payment.riderId}</td>
                  <td>₹{payment.amount}</td>
                  <td>{payment.status}</td>
                  <td>{new Date(payment.createdAt).toLocaleDateString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {activeTab === 'trips' && (
        <div className="tab-content">
          <h2>Trip Reports</h2>
          <table className="data-table">
            <thead>
              <tr><th>Trip ID</th><th>Status</th><th>Rider</th><th>Est. Fare</th><th>Final Fare</th><th>Date</th></tr>
            </thead>
            <tbody>
              {trips.map(trip => (
                <tr key={trip.id}>
                  <td>{trip.id}</td>
                  <td>{trip.status}</td>
                  <td>{trip.riderId}</td>
                  <td>{trip.estimatedFare ? `₹${trip.estimatedFare}` : '-'}</td>
                  <td>{trip.finalFare ? `₹${trip.finalFare}` : '-'}</td>
                  <td>{new Date(trip.createdAt).toLocaleDateString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
